import React, { useEffect, useMemo, useState } from "react";
import { BOOKINGS_KEY, DATA_EVENT, readJson, writeJson } from "../utils/storage";
import "./Dashboard.css";

const statuses = ["Pending", "Confirmed", "In Service", "Completed", "Cancelled"];

export default function AdminDashboard() {
  const [bookings, setBookings] = useState([]);
  useEffect(() => {
    const refresh = () => setBookings(readJson(BOOKINGS_KEY, []).sort((a, b) => new Date(b.bookedAt) - new Date(a.bookedAt)));
    refresh();
    const sync = (event) => (!event.key || event.key === BOOKINGS_KEY) && refresh();
    window.addEventListener("storage", sync);
    window.addEventListener(DATA_EVENT, sync);
    return () => {
      window.removeEventListener("storage", sync);
      window.removeEventListener(DATA_EVENT, sync);
    };
  }, []);

  const counts = useMemo(() => ({
    total: bookings.length,
    pending: bookings.filter((item) => (item.status || "Pending") === "Pending").length,
    completed: bookings.filter((item) => item.status === "Completed").length,
  }), [bookings]);

  const updateStatus = (id, status) => {
    writeJson(BOOKINGS_KEY, readJson(BOOKINGS_KEY, []).map((item) =>
      item.id === id ? { ...item, status, updatedAt: new Date().toISOString() } : item
    ));
  };

  return (
    <section className="dashboard-page section">
      <div className="container">
        <div className="dashboard-head"><div><span className="eyebrow">Admin Portal</span><h1>Service Dashboard</h1><p>Manage incoming customer bookings and live statuses.</p></div></div>
        <div className="stat-grid">
          <div><strong>{counts.total}</strong><span>Total bookings</span></div>
          <div><strong>{counts.pending}</strong><span>Awaiting action</span></div>
          <div><strong>{counts.completed}</strong><span>Completed</span></div>
        </div>
        {bookings.length ? <div className="admin-table-wrap"><table className="admin-table">
          <thead><tr><th>Customer</th><th>Bike &amp; Service</th><th>Date</th><th>Status</th></tr></thead>
          <tbody>{bookings.map((booking) => <tr key={booking.id}>
            <td><strong>{booking.name}</strong><small>{booking.phone}<br />{booking.userEmail}</small></td>
            <td><strong>{booking.serviceName}</strong><small>{booking.bikeBrand} {booking.bikeModel}<br />{booking.regNumber}</small></td>
            <td>{new Date(`${booking.date}T00:00:00`).toLocaleDateString("en-IN")}</td>
            <td><select value={booking.status || "Pending"} onChange={(event) => updateStatus(booking.id, event.target.value)}>{statuses.map((status) => <option key={status}>{status}</option>)}</select></td>
          </tr>)}</tbody>
        </table></div> : <div className="empty-state"><h2>No bookings received</h2><p>New customer requests will appear here automatically.</p></div>}
      </div>
    </section>
  );
}
